import React from "react";
import "../styles/main.css";

const ExtraCurricular = () => {
  return (
    <div className="extra-page">
      <div className="left-column">
        <h2>Extra Curricular</h2>
        <div className="info-box">
          <p>Foreign Languages</p>
          <p>Ethics and Personality Development</p>
          <p>Sports</p>
          <p>Music & Dance</p>
          <p>Art & Craft</p>
          <p>Tour & Trips</p>
        </div>
      </div>

      <div className="right-column">
        <h2>Extra Curricular</h2>
        <p>
          "Every child is an artist. The problem is how to remain an artist once we grow up." – Pablo Picasso
        </p>
        <p>
          "A Picture is a poem without words." – Horace
        </p>

        <h3>Art Activities:</h3>
        <ul>
          <li>Paint with Water colours, Crayon, Pencil Colours</li>
          <li>Block Painting</li>
          <li>Thread Painting</li>
        </ul>

        <h3>Craft Activities:</h3>
        <ul>
          <li>Pot Making and Decoration with colours and papers</li>
          <li>Purse making with waste material</li>
          <li>Origami</li>
        </ul>
        <p>(See Pictures in Gallery)</p>
      </div>
    </div>
  );
};

export default ExtraCurricular;
